p='test/server.test.js'; s=open(p).read()
s=s.replace('import { createServer } from "../src/server.js";','import { createServer } from "../src/server.js";\nimport { createStore } from "../src/store.js";')
s=s.replace("async function withServer(fn) {\n  const server = createServer().listen(0);","async function withServer(fn, store) {\n  const server = createServer(store).listen(0);")
s+='''
test("expired links return 410 and stop redirecting", async () => {
  let t = 0;
  const store = createStore({ now: () => t });
  await withServer(async (base) => {
    const res = await post(base, { url: "https://example.com/e", expiresInDays: 2 });
    const { code, expiresAt } = await res.json();
    assert.equal(expiresAt, 2 * 86400000);
    t = expiresAt - 1;
    assert.equal((await fetch(`${base}/${code}`, { redirect: "manual" })).status, 302);
    t = expiresAt;
    assert.equal((await fetch(`${base}/${code}`, { redirect: "manual" })).status, 410);
    const stats = await (await fetch(`${base}/stats/${code}`)).json();
    assert.equal(stats.clicks, 1);
    assert.equal(stats.expired, true);
  }, store);
});

test("rejects invalid expiresInDays", () =>
  withServer(async (base) => {
    for (const expiresInDays of [0, -1, 366, "7", null]) {
      assert.equal((await post(base, { url: "https://example.com", expiresInDays })).status, 400);
    }
    assert.equal((await post(base, { url: "https://example.com", expiresInDays: 365 })).status, 201);
  }));
'''
open(p,'w').write(s)
p='README.md'; s=open(p).read()
s=s.replace('taken → 409\n','taken → 409\n- Add `"expiresInDays": 7` (number, >0 and ≤365) to make the link expire; the response includes `expiresAt` (ms timestamp, `null` if it never expires). Expired links return 410\n',1)
s=s.replace('"createdAt", "lastClickedAt"}','"createdAt", "expiresAt", "expired", "lastClickedAt"}')
open(p,'w').write(s)
EOF
npm test 2>&1 | grep -E "^(✔|✖|ℹ (pass|fail))|not ok|^ok"

